'use client';

import { useApp } from '@/context/AppContext';
import { DollarSign, TrendingUp, TrendingDown, Wallet } from 'lucide-react';

export default function PayrollTable() {
  const { userRole, tutors, calculatePayroll, updateTutor } = useApp();
  const payrollData = calculatePayroll();

  if (userRole !== 'admin') {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6">
        <div className="flex items-center gap-2 text-yellow-800">
          <Wallet size={20} />
          <p className="font-medium">Admin access required to view payroll</p>
        </div>
      </div>
    );
  }

  const totalExpenditure = payrollData.reduce((sum, entry) => sum + entry.takeHomePay, 0);

  const handleVideoCountChange = (tutorId: string, value: string) => {
    updateTutor(tutorId, { videoCount: parseInt(value) || 0 });
  };

  const handleViolationChange = (tutorId: string, value: string) => {
    updateTutor(tutorId, { violations: parseInt(value) || 0 });
  };

  const handleLateDaysChange = (tutorId: string, value: string) => {
    updateTutor(tutorId, { lateDays: parseInt(value) || 0 });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-2 mb-4">
        <Wallet size={24} className="text-blue-600" />
        <h2 className="text-2xl font-bold text-gray-900">Payroll Management</h2>
      </div>

      <div className="bg-gradient-to-r from-blue-500 to-blue-600 rounded-lg shadow-lg p-6 text-white">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-blue-100 text-sm">Total Expenditure</p>
            <p className="text-3xl font-bold">Rp {totalExpenditure.toLocaleString()}</p>
          </div>
          <DollarSign size={48} className="text-blue-200" />
        </div>
      </div>

      <div className="bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tutor</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Videos</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Violations</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Late Days</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Earnings</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Bonuses</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Deductions</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Take-Home</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {payrollData.map(entry => {
              const tutor = tutors.find(t => t.id === entry.tutorId);
              return (
                <tr key={entry.tutorId}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                    {entry.tutorName}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <input
                      type="number"
                      min="0"
                      value={tutor?.videoCount || 0}
                      onChange={(e) => handleVideoCountChange(entry.tutorId, e.target.value)}
                      className="w-16 px-2 py-1 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <input
                      type="number"
                      min="0"
                      value={tutor?.violations || 0}
                      onChange={(e) => handleViolationChange(entry.tutorId, e.target.value)}
                      className="w-16 px-2 py-1 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <input
                      type="number"
                      min="0"
                      value={tutor?.lateDays || 0}
                      onChange={(e) => handleLateDaysChange(entry.tutorId, e.target.value)}
                      className="w-16 px-2 py-1 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    <div className="flex items-center gap-1">
                      <TrendingUp size={16} className="text-green-600" />
                      Rp {entry.totalEarnings.toLocaleString()}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-green-600">
                    <div className="flex items-center gap-1">
                      <TrendingUp size={16} />
                      +Rp {entry.totalBonuses.toLocaleString()}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-red-600">
                    <div className="flex items-center gap-1">
                      <TrendingDown size={16} />
                      -Rp {entry.totalDeductions.toLocaleString()}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-gray-900">
                    Rp {entry.takeHomePay.toLocaleString()}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <p className="text-sm text-blue-800">
          <strong>Note:</strong> Changes to video counts, violations, or late days will automatically recalculate the payroll amounts.
        </p>
      </div>
    </div>
  );
}