'use client';

import { useState } from 'react';
import { useApp } from '@/context/AppContext';
import { Plus, Calendar, BookOpen, Lock, Unlock, AlertCircle } from 'lucide-react';

export default function MeetingJournal() {
  const { userRole, classrooms, tutors, addMeeting, updateMeeting } = useApp();
  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [formData, setFormData] = useState({
    date: '',
    meetingNumber: 1,
    topic: '',
    status: 'completed' as 'completed' | 'hangus'
  });

  const selectedClassroom = classrooms.find(c => c.id === selectedClassroomId);
  const currentTutorClassrooms = userRole === 'tutor' 
    ? classrooms.filter(c => c.tutorId === 'tutor-1') // Assuming current tutor is tutor-1
    : classrooms;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedClassroomId) {
      addMeeting(selectedClassroomId, {
        ...formData,
        isLocked: false
      });
      setShowAddForm(false);
      setFormData({
        date: '',
        meetingNumber: formData.meetingNumber + 1,
        topic: '',
        status: 'completed'
      });
    }
  };

  const toggleMeetingStatus = (classroomId: string, meetingId: string) => {
    const classroom = classrooms.find(c => c.id === classroomId);
    const meeting = classroom?.meetings.find(m => m.id === meetingId);
    if (meeting) {
      const newStatus = meeting.status === 'completed' ? 'hangus' : 'completed';
      updateMeeting(classroomId, meetingId, {
        status: newStatus,
        isLocked: newStatus === 'hangus'
      });
    }
  };

  const restoreMeeting = (classroomId: string, meetingId: string) => {
    updateMeeting(classroomId, meetingId, {
      status: 'completed',
      isLocked: false
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-2">
        <BookOpen size={24} className="text-blue-600" />
        <h2 className="text-2xl font-bold text-gray-900">Meeting Journal</h2>
      </div>

      <div className="bg-white rounded-lg shadow border border-gray-200 p-6">
        <div className="mb-4">
          <label className="block text-sm font-medium text-gray-700 mb-2">Select Classroom</label>
          <select
            value={selectedClassroomId}
            onChange={(e) => setSelectedClassroomId(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Select a classroom...</option>
            {currentTutorClassrooms.map(classroom => {
              const tutor = tutors.find(t => t.id === classroom.tutorId);
              return (
                <option key={classroom.id} value={classroom.id}>
                  {classroom.name} ({tutor?.name || 'Unassigned'})
                </option>
              );
            })}
          </select>
        </div>

        {selectedClassroom && (
          <>
            {userRole !== 'admin' && (
              <div className="mb-4">
                <button
                  onClick={() => setShowAddForm(!showAddForm)}
                  className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
                >
                  <Plus size={20} />
                  {showAddForm ? 'Cancel' : 'Add Meeting'}
                </button>
              </div>
            )}

            {showAddForm && (
              <div className="bg-gray-50 rounded-lg p-4 mb-4">
                <h3 className="font-semibold text-gray-900 mb-3">Add New Meeting</h3>
                <form onSubmit={handleSubmit} className="space-y-3">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
                      <input
                        type="date"
                        value={formData.date}
                        onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Meeting Number</label>
                      <input
                        type="number"
                        min="1"
                        value={formData.meetingNumber}
                        onChange={(e) => setFormData({ ...formData, meetingNumber: parseInt(e.target.value) || 1 })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                        required
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Lesson Topic</label>
                    <input
                      type="text"
                      value={formData.topic}
                      onChange={(e) => setFormData({ ...formData, topic: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                      required
                    />
                  </div>
                  <button
                    type="submit"
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                  >
                    Add Meeting
                  </button>
                </form>
              </div>
            )}

            <div className="space-y-3">
              <h3 className="font-semibold text-gray-900">Meeting History</h3>
              {selectedClassroom.meetings.length === 0 ? (
                <p className="text-gray-500 text-sm">No meetings recorded yet.</p>
              ) : (
                <div className="space-y-2">
                  {selectedClassroom.meetings.map(meeting => (
                    <div
                      key={meeting.id}
                      className={`border rounded-lg p-4 ${
                        meeting.status === 'hangus'
                          ? 'border-red-300 bg-red-50'
                          : 'border-gray-200 bg-white'
                      }`}
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Calendar size={16} className="text-gray-500" />
                            <span className="text-sm text-gray-600">{meeting.date}</span>
                            <span className="text-sm font-medium text-gray-900">
                              Meeting #{meeting.meetingNumber}
                            </span>
                            {meeting.status === 'hangus' && (
                              <span className="flex items-center gap-1 text-red-600 text-sm">
                                <AlertCircle size={14} />
                                Hangus/Locked
                              </span>
                            )}
                          </div>
                          <p className="text-gray-900">{meeting.topic}</p>
                          {selectedClassroom.ldrTag !== 'none' && meeting.status === 'completed' && (
                            <div className="mt-2 text-sm text-green-600">
                              ✓ LDR bonus applied ({selectedClassroom.ldrTag})
                            </div>
                          )}
                        </div>
                        {userRole === 'admin' && (
                          <div className="flex gap-2 ml-4">
                            {meeting.status === 'hangus' ? (
                              <button
                                onClick={() => restoreMeeting(selectedClassroom.id, meeting.id)}
                                className="flex items-center gap-1 px-3 py-1 bg-green-100 text-green-700 rounded hover:bg-green-200 transition-colors text-sm"
                              >
                                <Unlock size={14} />
                                Restore
                              </button>
                            ) : (
                              <button
                                onClick={() => toggleMeetingStatus(selectedClassroom.id, meeting.id)}
                                className="flex items-center gap-1 px-3 py-1 bg-red-100 text-red-700 rounded hover:bg-red-200 transition-colors text-sm"
                              >
                                <Lock size={14} />
                                Lock
                              </button>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
}